export const words=text=>text.trim().split(/\s+/).filter(Boolean).length;
export function excerpts(text){const paragraphs=text.split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean),result=[];for(const p of paragraphs){const sentences=p.match(/[^.!?]+(?:[.!?]+[”"»]?|$)/g)||[p];let chunk='';for(const s of sentences){if(words(chunk+' '+s)>180&&words(chunk)>=40){result.push(chunk.trim());chunk=''}chunk+=' '+s;if(words(chunk)>=80){result.push(chunk.trim());chunk=''}}if(chunk.trim()){if(words(chunk)>=40)result.push(chunk.trim());else if(result.length&&words(result.at(-1)+' '+chunk)<=180)result[result.length-1]+=' '+chunk.trim();else if(paragraphs.length===1)result.push(chunk.trim())}}return [...new Set(result.length?result:[text.trim()])].filter(Boolean)}
export function randomExcerpt(text,previous='',random=Math.random){const all=excerpts(text),choices=all.filter(x=>x!==previous);const pool=choices.length?choices:all;return {text:pool.length?pool[Math.floor(random()*pool.length)]:'',count:all.length}}
export function chatPrompt(r){return `请帮我分析下面这段葡萄牙语翻译练习。\n\n要求：\n1. 先评价我的译文是否准确\n2. 指出遗漏、误译和不自然表达\n3. 解释重要葡语词汇和语法\n4. 给出更自然的${r.mode==='ZH-PT'?'葡萄牙语':'中文'}参考译文\n5. 按 CAPLE C1 / 翻译专业学习水平解释\n\n【新闻标题】\n${r.articleTitle}\n\n【来源】\n${r.source}\n\n【${r.mode==='ZH-PT'?'中文':'葡萄牙语'}原文】\n${r.originalExcerpt}\n\n【我的译文】\n${r.userTranslation}`}
export function safeLink(url){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
